fn array_split(mut a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();
    if n > 1 {
        // split_off takes the tail [mid..] and leaves the head in `a`
        let mid = n / 2;
        let tail = a.split_off(mid);
        (a, tail)
    } else {
        // for n == 0 or 1, we don't need a strict split
        (Vec::new(), a)
    }
}

